-- Initial schema.
--
-- Written with IF NOT EXISTS on purpose: databases created before migrations
-- existed (with `pnpm db:push`) already have these tables. Running this file
-- against one of them records the migration as applied without touching the
-- data, so every deployment ends up on the same migration history. Later
-- migrations are generated by `pnpm db:generate` and need no such care.
CREATE TABLE IF NOT EXISTS "sessions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"title" text NOT NULL,
	"host_pubkey" text NOT NULL,
	"host_name" text NOT NULL,
	"status" text DEFAULT 'waiting' NOT NULL,
	"invite_code" text NOT NULL,
	"participant_count" integer DEFAULT 1 NOT NULL,
	"max_participants" integer DEFAULT 8 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"started_at" timestamp with time zone,
	"ended_at" timestamp with time zone,
	CONSTRAINT "sessions_invite_code_unique" UNIQUE("invite_code")
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "participants" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"session_id" uuid NOT NULL,
	"pubkey" text NOT NULL,
	"display_name" text NOT NULL,
	"role" text DEFAULT 'guest' NOT NULL,
	"joined_at" timestamp with time zone DEFAULT now() NOT NULL,
	"left_at" timestamp with time zone
);
